package secretbunker

import (
	"encoding/hex"
	"reflect"
	"testing"
)

// CBOR golden vectors generated by the Rust implementation
// (secret-bunker-iroh: proto::tests::wire_format_is_stable). The two test
// suites share these bytes; a mismatch means the wire contract broke.

func TestRequestGoldenVectors(t *testing.T) {
	cases := []struct {
		name string
		got  []byte
		want string
	}{
		{"get", encGet("prod", "db"), "a163476574a26567726f75706470726f64646e616d65626462"},
		{
			"put",
			encPut("g", "n", []byte{1, 2, 255}, 300),
			"a163507574a46567726f75706167646e616d65616e6576616c7565430102ff7065787065637465645f76657273696f6e19012c",
		},
		{"list-groups", encListGroups(), "6a4c69737447726f757073"},
		{"grant", encGrant("g", "id", 7), "a1654772616e74a36567726f75706167686964656e74697479626964657065726d7307"},
	}
	for _, c := range cases {
		if got := hex.EncodeToString(c.got); got != c.want {
			t.Errorf("%s: encoded %s, want %s", c.name, got, c.want)
		}
	}
}

func TestResponseGoldenVectors(t *testing.T) {
	cases := []struct {
		name string
		hex  string
		want Response
	}{
		{"denied", "6644656e696564", Denied{}},
		{
			"secret",
			"a166536563726574a26576616c75654268696776657273696f6e1880",
			Secret{Value: []byte("hi"), Version: 128},
		},
		{
			"names",
			"a1654e616d6573828261610182616202",
			Names{{Name: "a", Version: 1}, {Name: "b", Version: 2}},
		},
		{
			"groups",
			"a16647726f757073a26d736572766963655f61646d696ef56667726f75707381a2646e616d656167657065726d7305",
			Groups{ServiceAdmin: true, Groups: []GroupInfo{{Name: "g", Perms: 5}}},
		},
		{"failed", "a1664661696c6564a166726561736f6e626e6f", Failed{Reason: "no"}},
		{
			"conflict",
			"a16f56657273696f6e436f6e666c696374a16763757272656e7419ffff",
			VersionConflict{Current: 65535},
		},
	}
	for _, c := range cases {
		buf, err := hex.DecodeString(c.hex)
		if err != nil {
			t.Fatal(err)
		}
		got, err := decodeResponse(buf)
		if err != nil {
			t.Fatalf("%s: decode: %v", c.name, err)
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("%s: decoded %#v, want %#v", c.name, got, c.want)
		}
	}
}

func TestDecodeRejectsMalformedInput(t *testing.T) {
	cases := map[string]string{
		"empty":                "",
		"integer payload":      "00",
		"unknown unit variant": "63466f6f",     // "Foo"
		"unknown map variant":  "a163466f6f00", // {"Foo": 0}
		"two-entry envelope":   "a2624f6b00644f6b323100",
		"trailing bytes":       "6644656e69656400",
		"truncated envelope":   "a166536563726574", // {"Secret": <missing>}
	}
	for name, h := range cases {
		buf, err := hex.DecodeString(h)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := decodeResponse(buf); err == nil {
			t.Errorf("%s (%s): expected decode error, got none", name, h)
		}
	}
}
